    @_mutmut_mutated(mutants_xǁCodeExplorerǁ_collect_files__mutmut)
    def _collect_files(self, target_paths: list[str] | None = None) -> list[Path]:
        """분석 대상 파일 수집"""
        files = []

        # 제외 패턴
        exclude_dirs = {
            "__pycache__",
            ".git",
            ".venv",
            "venv",
            "env",
            "node_modules",
            "dist",
            "build",
            ".pytest_cache",
            ".mypy_cache",
            ".ruff_cache",
            "target",
            "vendor",
            ".idea",
            ".vscode",
            "__MACOSX",
        }
        exclude_patterns = {
            "*.pyc",
            "*.pyo",
            "*.pyd",
            "*.so",
            "*.dll",
            "*.dylib",
            "*.min.js",
            "*.min.css",
            "*.map",
            "*.lock",
            "package-lock.json",
            "yarn.lock",
            "pnpm-lock.yaml",
            "Cargo.lock",
            "go.sum",
            "poetry.lock",
            "uv.lock",
        }

        search_paths = (
            [self.workspace / p for p in target_paths] if target_paths else [self.workspace]
        )

        for search_path in search_paths:
            if not search_path.exists():
                continue

            for root, dirs, filenames in os.walk(search_path):
                # 제외 디렉토리 필터링
                dirs[:] = [d for d in dirs if d not in exclude_dirs]

                for filename in filenames:
                    # 제외 패턴 체크
                    skip = False
                    for pattern in exclude_patterns:
                        if self._match_pattern(filename, pattern):
                            skip = True
                            break
                    if skip:
                        continue

                    # 코드 파일만 (확장자 기반)
                    if self._is_code_file(filename):
                        files.append(Path(root) / filename)

        return files

