    @_mutmut_mutated(mutants_xǁCodeExplorerǁ_extract_python_symbols__mutmut)
    def _extract_python_symbols(self, file_path: Path, content: str) -> list[CodeSymbol]:
        """Python 심볼 추출 (AST 기반)"""
        symbols = []
        rel_path = file_path.relative_to(self.workspace)

        try:
            tree = ast.parse(content)
        except SyntaxError:
            return symbols

        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                symbols.append(
                    CodeSymbol(
                        name=node.name,
                        type="function" if not self._is_method(node, tree) else "method",
                        file_path=str(rel_path),
                        line_start=node.lineno,
                        line_end=node.end_lineno or node.lineno,
                        signature=self._get_function_signature(node),
                        docstring=ast.get_docstring(node) or "",
                    )
                )
            elif isinstance(node, ast.ClassDef):
                symbols.append(
                    CodeSymbol(
                        name=node.name,
                        type="class",
                        file_path=str(rel_path),
                        line_start=node.lineno,
                        line_end=node.end_lineno or node.lineno,
                        signature=f"class {node.name}",
                        docstring=ast.get_docstring(node) or "",
                    )
                )
            elif isinstance(node, ast.AsyncFunctionDef):
                symbols.append(
                    CodeSymbol(
                        name=node.name,
                        type=(
                            "async_function" if not self._is_method(node, tree) else "async_method"
                        ),
                        file_path=str(rel_path),
                        line_start=node.lineno,
                        line_end=node.end_lineno or node.lineno,
                        signature=self._get_async_function_signature(node),
                        docstring=ast.get_docstring(node) or "",
                    )
                )

        return symbols

