    @_mutmut_mutated(mutants_xǁCodeExplorerǁ_find_test_files__mutmut)
    def _find_test_files(self, files: list[FileInfo]) -> list[str]:
        """테스트 파일 찾기"""
        test_files = []

        for file_info in files:
            name = Path(file_info.path).name
            stem = Path(file_info.path).stem

            # 패턴 매칭
            is_test = (
                name.startswith("test_")
                or name.endswith("_test.py")
                or name.endswith(".test.js")
                or name.endswith(".test.ts")
                or name.endswith(".spec.js")
                or name.endswith(".spec.ts")
                or stem.endswith("_test")
                or stem.endswith("Test")
                or "test" in Path(file_info.path).parts
                or "__tests__" in Path(file_info.path).parts
                or "tests" in Path(file_info.path).parts
            )

            if is_test:
                test_files.append(file_info.path)

        return test_files

